import * as wmill from "windmill-client";

// Collective funnel, LIVE since 2026-11-12: page template in datatable dashboard_pages (name "funnel_live"), data in collective_funnel_data
// (name "live", rebuilt every 15 min by f/sales_tracker/collective_funnel_refresh). The data is put into the page on each request.
// The old 2026-11-05 snapshot stays in dashboard_pages (name "funnel") as a fallback. Change folder: ~/Work/collective_funnel_live
// The shell is public; the page itself needs today's date (IST, DDMMYYYY) as passcode, same as Collective conversations.
// Change folder: ~/Work/Sprint_bot/changes/2026-11-06_share_dashboards
type Query = Record<string, string | string[] | undefined>;
const NAME = "funnel";

export async function preprocessor(event: { kind: string; query?: Query; headers?: Record<string, string | string[] | undefined> }) {
  // Windmill serves the page in a CSP sandbox (origin "null"), so CORS only lets "Authorization" through.
  const header = (n: string) => { const v = Object.entries(event.headers ?? {}).find(([k]) => k.toLowerCase() === n)?.[1]; return Array.isArray(v) ? v[0] : v ?? ""; };
  return { query: event.kind === "http" ? event.query ?? {} : {}, passcode: header("authorization").match(/^Passcode\s+(.*)$/i)?.[1] ?? "" };
}

export async function main(query: Query = {}, passcode = "") {
  if (query.__data === "1") {
    const today = new Intl.DateTimeFormat("en-GB", { timeZone: "Asia/Kolkata", day: "2-digit", month: "2-digit", year: "numeric" }).format(new Date()).replace(/\D/g, "");
    if (String(passcode).replace(/\D/g, "") !== today)
      return { windmill_status_code: 401, windmill_content_type: "application/json", result: { error: "passcode" } };
    const sql = wmill.datatable("main");
    const [tpl] = await sql`SELECT html FROM dashboard_pages WHERE name = 'funnel_live'`.fetch() as any[];
    const [dat] = await sql`SELECT data FROM collective_funnel_data WHERE name = 'live'`.fetch() as any[];
    let html: string;
    if (tpl?.html && dat?.data) html = tpl.html.replace("__FUNNEL_DATA__", () => JSON.stringify(dat.data).replace(/</g, "\\u003c"));
    else html = ((await sql`SELECT html FROM dashboard_pages WHERE name = ${NAME}`.fetch()) as any[])[0]?.html ?? "<p>Not published yet.</p>";
    return { windmill_content_type: "application/json; charset=utf-8", windmill_headers: { "Cache-Control": "no-store, private", "X-Robots-Tag": "noindex" },
      result: { html } };
  }
  return { windmill_content_type: "text/html; charset=utf-8", windmill_headers: { "Cache-Control": "no-store", "X-Robots-Tag": "noindex, nofollow" }, result: SHELL };
}

const SHELL = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex,nofollow"><meta name="referrer" content="no-referrer"><title>Collective funnel &middot; Beforest</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500&family=Fraunces:opsz,wght@9..144,300&display=swap" rel="stylesheet">
<style>body{margin:0;background:#fdfbf7;color:#342e29;font:400 14px/1.55 Inter,system-ui,sans-serif}
.gate{max-width:360px;margin:18vh auto;text-align:center;padding:0 16px}.eyebrow{font-size:11.5px;letter-spacing:1.4px;text-transform:uppercase;color:#8a8078}
h1{font:300 40px/1.05 "ABC Arizona Flare",Fraunces,Georgia,serif;margin:6px 0 0}
input{width:100%;padding:12px 16px;border:1px solid #ebe4d9;border-radius:12px;font:15px Inter,sans-serif;margin:18px 0 10px;background:#fff;box-sizing:border-box}
button{width:100%;padding:12px;border:0;border-radius:12px;background:#0d2818;color:#fdfbf7;font:500 14px Inter,sans-serif;cursor:pointer}.err{color:#86312b;font-size:13px;min-height:18px}</style></head>
<body><div class="gate"><div class="eyebrow">Beforest</div><h1>Collective funnel</h1><input id="pc" type="password" inputmode="numeric" placeholder="Passcode" autocomplete="off"><div class="err" id="err"></div><button id="go">Open</button></div>
<script>
const go = async () => {
  const pc = document.getElementById("pc").value.trim(), err = document.getElementById("err");
  if (!pc) { err.textContent = "Enter the passcode first"; return; }
  err.textContent = "Loading…";
  try {
    const r = await fetch(location.pathname + "?__data=1", { headers: { Authorization: "Passcode " + pc }, cache: "no-store" });
    if (r.status === 401) { err.textContent = "That passcode did not work"; return; }
    const { html } = await r.json();
    document.open(); document.write(html); document.close();
  } catch (e) { err.textContent = "Could not load, try again"; }
};
document.getElementById("go").onclick = go;
document.getElementById("pc").onkeydown = e => { if (e.key === "Enter") go(); };
</script></body></html>`;
